FILES_DIR="/app/filesystem/GAIA/2023/validation"




if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--local_dir", default="~/data/gaia_dev")
    parser.add_argument("--metadata_path", default="/data3/workhome/fanshengda/AgentCPM-MCP/src/gaia_test/GAIA/2023/validation/metadata.jsonl")
    args = parser.parse_args()

    data_source = "gaia_dev"
    
    metadata = pd.read_json(args.metadata_path, lines=True)


    # add a row to each data item that represents a unique id

    def process_fn(example, idx):
        question = example['Question']

        system_message = deepcopy(gaia_system_prompt_content)
        if example['file_name']:
            full_path = os.path.join(FILES_DIR, example['file_name']).replace('\\', '/')
            system_message += "\n\n--- Associated File ---\n"
            system_message += f"A file is associated with this task.\n"
            system_message += f"The absolute path to this file for your tools is: {full_path}\n"

            system_message += (
                "You MUST use your code interpreter to write and execute Python code to analyze this file.\n"
            )
        solution = str(example['Final answer'])

        data = {
            "data_source": data_source,
            "prompt": [
                {
                    "role": "system",
                    "content": system_message,
                },
                {
                "role": "user",
                "content": question,
            }],
            "ability": "fact-reasoning",
            "reward_model": {
                "style": "rule",
                "ground_truth": solution
            },
            "extra_info": {
                'split': 'dev',
                'index': idx,
                'task_id': example['task_id'],
                'Level': example['Level'],
                'Annotator Metadata': example['Annotator Metadata'],
                'question': question,
                "need_tools_kwargs": True,
                # Ensure non-empty per-tool kwargs to avoid PyArrow struct<> write error
                # Ref: ArrowNotImplementedError: Cannot write struct type with no child field
                "tools_kwargs": {
                    item['function']['name']: {
                        "create_kwargs": {"ground_truth": solution}
                    }
                    for item in gaia_tools_content
                },
            }
        }
        return data




    train_dataset = pd.DataFrame([
        process_fn(row, idx) for idx, row in metadata.iterrows()
    ])


    local_dir = args.local_dir

    train_dataset.to_parquet(os.path.join(local_dir, "dev.parquet"))